sys_script_client.script:
function onLoad() {
    if (g_scratchpad.user) {
        var userID = g_user.userID;
        var msg = getMessage("You are viewing a record which is already assigned to " + g_scratchpad.user + ". Do you still want to work on it?");
        g_modal.confirm(getMessage("Confirmation"), msg, function(confirmed) {
            if (confirmed) {
                g_form.setValue('assigned_to', userID);
                g_form.save();
            } else {
                //do nothing
            }
        });
    } else if (g_scratchpad.flag) {
        g_form.setValue('assigned_to', g_user.userID);

        g_form.save();
        g_form.reload();
    }
	g_form.setReadOnly('assigned_to', true);
}
